!function(e){function i(i){for(var t,a,o=i[0],m=i[1],d=i[2],g=0,s=[];g<o.length;g++)a=o[g],Object.prototype.hasOwnProperty.call(n,a)&&n[a]&&s.push(n[a][0]),n[a]=0;for(t in m)Object.prototype.hasOwnProperty.call(m,t)&&(e[t]=m[t]);for(c&&c(i);s.length;)s.shift()();return p.push.apply(p,d||[]),r()}function r(){for(var e,i=0;i<p.length;i++){for(var r,a=p[i],o=!0,m=1;m<a.length;m++)r=a[m],0!==n[r]&&(o=!1);o&&(p.splice(i--,1),e=t(t.s=a[0]))}return e}function t(i){if(a[i])return a[i].exports;var r=a[i]={i:i,l:!1,exports:{}};return e[i].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var a={},n={54:0},p=[];t.m=e,t.c=a,t.d=function(e,i,r){t.o(e,i)||Object.defineProperty(e,i,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,i){if(1&i&&(e=t(e)),8&i)return e;if(4&i&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&i&&"string"!=typeof e)for(var a in e)t.d(r,a,function(i){return e[i]}.bind(null,a));return r},t.n=function(e){var i=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(i,"a",i),i},t.o=function(e,i){return Object.prototype.hasOwnProperty.call(e,i)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=i,o=o.slice();for(var d=0;d<o.length;d++)i(o[d]);var c=m;p.push([224,0]),r()}({224:function(e,i,r){"use strict";r.r(i);var t=r(0);Object(t.a)("de","army",r(225),r(1))},225:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轻武器","link":"de_army#de_army_iw"}],"model":"MG34机枪","description":"<p>MG34机枪是德国陆军在二战期间大量使用的一种十分出名的机枪，该机枪具有轻机枪的重量和便携性，又具备重机枪的火力和射程，是世界上第一种通用机枪。MG34机枪在1935年开始量产，到停产时一共生产了5万7千多支，1942年该机枪逐步被MG42机枪替代，但仍有不少在德军中服役到二战结束。</p><p>MG34机枪作为轻机枪使用时，一般使用2脚支架，采用的是50发弹链或75发双室弹鼓；当作为重机枪使用量，则采用三脚支架和250发弹链，并可作防空机枪使用。在战场上，该机枪是德军一种威力极大的火力压制武器。</p><p>MG34机枪设计精良，但造价甚高，制造工艺复杂，部分零件还需使用贵金属制造，而机枪是二战战场上大量需求且容易战损的武器，因此德军后来就在此机枪的基础上，研制出成本较低、性能更好的的MG42机枪以作替代。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_iwMG34_11.jpg","description":"<h6>MG34机枪</h6><p></p><p>技术数据：</p><p>口径：7.92毫米；</p><p>枪全长：1219毫米，枪管长：627毫米，枪全重：12.1千克；</p><p>最大射速：900发/分钟；枪口初速：755米/秒；</p><p>有效射程：1200米；</p><p>弹容量与供弹方式：50发弹链、75发双室弹鼓，250发弹链（用5条50发弹链串联）。</p>","caption":""}],"part2title":"战场上的MG34机枪","part2description":"","part2content":[{"image":"imgs/de/army/de_army_iwMG34_21.jpg","description":"二战战场上的德军MG34机枪射手。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_22.jpg","description":"（图左）二战战场上德军第7空降师一名肩扛MG34机枪的射手。（图右）二战东线战场上持MG34机枪奔向阵地的一名MG34机枪射手。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_23.jpg","description":"（图左）二战东线战场斯大林格勒，一名精神疲惫的德军MG34机枪手。（图右）二战东线战场，一名手提MG34机枪在田地中紧张地隐蔽前进的德军士兵。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_24.jpg","description":"1939年，在入侵波兰期间，一个德国步兵分队跟随在一辆Ⅰ号坦克后面，准备对波兰军队发动进攻，其中后面一名士兵紧握着一挺MG34机枪。在二战初期，MG34机枪是德军步兵必配的主要火力压制武器。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_25.jpg","description":"1940年5月，西线法国战场，一个德国武装党卫军的MG34重机枪组正在阵地上作战，MG34机枪支在三脚架上，一弹药手伏在机枪旁用子弹链给机枪供弹。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_26.jpg","description":"1941年10月，东线苏联战场，在德军的“台风”战役中，德国中央集团军群正发动全力向苏联首都莫斯科进攻，德军的一个MG34机枪组正在废墟中转移前进阵地，前面的机枪射手抱着带子弹链的一挺MG34机枪，后面的弹药手则背着三脚 架，手中拿着2个弹药箱。图中情景反映了当时战斗的激烈程度。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_27.jpg","description":"1941年冬天，东线苏联战场，进攻莫斯科的德国中央集团军群已转入防御，面对苏军即将到来的反攻，一个武装党卫军的MG34重机枪组在防御阵地上作好了战斗准备，机枪射手用望远镜观察着前方动静，机枪旁放着的弹药箱，弹药手也紧张地注视着前方。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_28.jpg","description":"1942年2月，在大雪纷飞的东线苏联战场，德军近10万人被苏联西北方面军包围在杰米扬斯克地区。包围圈内，德国武装党卫军第3“骷髅”装甲师的一个MG34机枪组正在雪地中为突围德军提供火力支援。图中的德军都穿着带头套的白色防寒风雨衣作战，可见当时的气温之低和风雪之大。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_29.jpg","description":"1942年秋天，东线苏联战场斯大林格勒，德军一个MG34机枪组在一个谷仓附近为进攻德军提供火力支援。在这个谷仓阵地中，50名苏军曾抵挡了德军三个师的轮番进攻。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_30.jpg","description":"东线苏联战场，埋伏在草丛中的德军一个MG34机枪射手正在向上方目标瞄准。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_31.jpg","description":"1942年，非洲战场，德国非洲军团的一个MG34机枪组在一个石堆阵地中作战斗警戒。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_32.jpg","description":"二战东线苏联战场，德军一个MG34重机枪班阵地，MG34安装在三脚架上，班长正用望远镜观察着地平线上敌军的活动。注意：该机枪装上了一个光学瞄准镜。在德军步兵中，一个标准的MG34机枪组由3人组成，在行军时，射手拿机枪，弹药手提弹药箱，还有一名负责背一支备用枪管（在机枪枪管因射击过热时更换）。而在作战时，除射手和弹药手各司其职外，还会有一人负责观察战况指挥射击。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_33.jpg","description":"1942年冬天，东线苏联战场，雪地树林中，德军一个MG34重机枪组正在作战斗警戒，随时准备为德军步兵提供火力支援。在这样的冬季条件下作战，对机枪组提出了严峻的挑战，关键问题是要防止枪的运动部件在冰冷的情况下结冰，因此严格按操作程序射击和采取正确的存放方法是十分重要的。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_34.jpg","description":"一个德国伞兵的防空机枪组正用支在Dreibein 34AA型三脚架（德语中“Dreibein”即三脚架的意思）上进行对空射击；MG34在枪管上装有一个用于对空瞄准的环形瞄准镜。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_35.jpg","description":"1942年，东线苏联战场高加索地区，德军一个步兵班正在涉水过河。注意：机枪手扛着的那挺MG34机枪装的是一个50发弹匣，这对机枪手来说，行军时会比较方便，但在战斗中，德军会更多使用50/250发的子弹链。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_36.jpg","description":"1941年冬天，二战东线苏联战场，正在向苏联内陆进军的一支德军部队，走在前面的一个机枪手扛着一挺MG34机枪，表情十分轻松。入侵苏联初期，由于德军连续打了多个围歼战，所以士气还是不错的。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_37.jpg","description":"二战战场上，伏在铁轨上作战的一个德军MG34轻机枪组。","caption":""},{"image":"imgs/de/army/de_army_iwMG34_38.jpg","description":"二战战场上，正在射击的一个德军MG34重机枪组。","caption":""}]}')}});